INSERT INTO assistants (organization_id, public_key, name) SELECT id, 'utilmo', 'Utilmo AI' FROM organizations WHERE slug = 'utilmo' ON CONFLICT (public_key) DO NOTHING;
INSERT INTO assistant_settings (assistant_id, organization_id, settings) VALUES ((SELECT id FROM assistants WHERE public_key = 'utilmo'), (SELECT id FROM organizations WHERE slug = 'utilmo'), '{"behavior":{"assistantName":"Assistant Utilmo","companyName":"Utilmo","defaultLanguage":"fr","tone":"friendly_professional","companyDescription":{"fr":"Utilmo est une plateforme immobilière tout-en-un développée au Québec (CRM, sites web avec intégration Centris/CREA, génération de leads, IA et automatisation) pour les courtiers et agences immobilières. Utilmo appartient à Marketing Websites inc. (Montréal).","en":"Utilmo is an all-in-one real estate platform built in Quebec (CRM, websites with Centris/CREA integration, lead generation, AI and automation) for real estate brokers and agencies. Utilmo is owned by Marketing Websites Inc. (Montreal)."},"welcome":{"fr":"Bonjour 👋 Bienvenue chez Utilmo ! Je suis votre assistant virtuel. Je peux répondre à vos questions et vous aider à trouver les meilleures solutions pour votre entreprise immobilière. Qu''aimeriez-vous améliorer en priorité ?","en":"Hi 👋 Welcome to Utilmo! I''m your virtual assistant. I can answer your questions and help you find the best solutions for your real estate business. What would you like to improve first?"},"suggestions":{"fr":["Générer plus de leads","Améliorer ma visibilité","Découvrir le CRM","Automatiser mes suivis","Créer mon site web","J''ai besoin de soutien"],"en":["Generate more leads","Improve my visibility","Discover the CRM","Automate my follow-ups","Build my website","I need support"]},"maxResponseWords":120,"askBudget":false,"contactCaptureAfterTurns":3,"escalation":{"unresolvedThreshold":2,"supportEmail":"support@utilmo.ca","supportPhone":"514-360-2187","salesPhone":"514-360-2187"}},"ai":{"provider":"anthropic","responseModel":"claude-opus-5-5","analysisModel":"claude-haiku-5-5","effort":"low","maxOutputTokens":1500,"retrievalTopK":6,"embeddings":"none"},"booking":{"provider":"calendly","url":"https://calendly.com/utilmocrm/30-minute-meeting-clone","label":{"fr":"Réserver une démo gratuite","en":"Book a free demo"}},"appearance":{"primaryColor":"#4c2b7b","accentColor":"#f47421","backgroundColor":"#ffffff","textColor":"#1d2124","radius":20,"fontFamily":"Montserrat","headingFontFamily":"Poppins","loadGoogleFonts":true,"logoUrl":"/brand/utilmo-logo_2024.png","avatarUrl":"/brand/utilmo-icon.png","launcherPosition":"right","launcherStyle":"circle","attentionAnimation":true,"teaser":{"enabled":true,"delaySeconds":8,"text":{"fr":"Une question sur Utilmo ? Je suis là pour vous aider.","en":"Questions about Utilmo? I''m here to help."}},"inlineHeight":620,"mobileFullscreen":true},"privacy":{"noticeVersion":"2026-11-23","notice":{"fr":"Cet assistant utilise l''IA. Vos messages servent à répondre à vos questions et, si vous nous laissez vos coordonnées, à vous recontacter. Ne partagez aucun mot de passe ni renseignement de paiement.","en":"This assistant uses AI. Your messages are used to answer your questions and, if you share your contact details, to follow up with you. Never share passwords or payment information."},"privacyPolicyUrl":{"fr":"https://utilmo.com/fr/politique-de-confidentialite/","en":"https://utilmo.com/privacy-policy/"},"conversationRetentionDays":365,"sessionRetentionDays":30},"limits":{"messagesPerMinute":8,"messagesPerConversation":80,"dailyMessageCap":3000,"maxMessageChars":2000}}'::jsonb) ON CONFLICT (assistant_id) DO NOTHING;
