INSERT INTO recommended_services (organization_id, assistant_id, key, name, description, categories, problems, features, price_note, next_step, url, sort) VALUES ((SELECT id FROM organizations WHERE slug = 'utilmo'), (SELECT id FROM assistants WHERE public_key = 'utilmo'), 'crm', '{"fr":"CRM immobilier Utilmo","en":"Utilmo real estate CRM"}'::jsonb, '{"fr":"CRM conçu pour les courtiers : contacts, pipelines, tâches, rappels, appels/SMS/courriels et suivis automatisés.","en":"CRM built for brokers: contacts, pipelines, tasks, reminders, calls/SMS/e-mails and automated follow-ups."}'::jsonb, ARRAY['CRM','AUTOMATION']::text[], '{"fr":["Leads perdus ou oubliés","Suivis manuels","Contacts dispersés","Gestion d''une grande base de contacts"],"en":["Lost or forgotten leads","Manual follow-ups","Scattered contacts","Managing a large contact database"]}'::jsonb, '{"fr":["Pipelines, tâches et rappels","Notification SMS et courriel à chaque nouveau lead","Appels, SMS et courriels depuis Utilmo, composeur et enregistrement d''appels","Campagnes automatisées courriel/SMS","Intégration Centris ou CREA","Intégrations Google Calendar, Office 365, Mailchimp","Application mobile"],"en":["Pipelines, tasks and reminders","SMS and e-mail notification for every new lead","Calls, SMS and e-mails from Utilmo, dialer and call recording","Automated e-mail/SMS campaigns","Centris or CREA integration","Google Calendar, Office 365, Mailchimp integrations","Mobile app"]}'::jsonb, '{"fr":"79,99 $/mois, sans frais de mise en place (site web non inclus). Essai gratuit offert.","en":"$79.99/month, no setup fees (website not included). Free trial available."}'::jsonb, 'demo', 'https://utilmo.com/fr/crm-leads/', 10) ON CONFLICT (assistant_id, key) DO NOTHING;
INSERT INTO recommended_services (organization_id, assistant_id, key, name, description, categories, problems, features, price_note, next_step, url, sort) VALUES ((SELECT id FROM organizations WHERE slug = 'utilmo'), (SELECT id FROM assistants WHERE public_key = 'utilmo'), 'lead_generation', '{"fr":"Génération de leads acheteurs et vendeurs","en":"Buyer and seller lead generation"}'::jsonb, '{"fr":"Pages de publicité (landing pages) et campagnes publicitaires ciblées, avec leads importés directement dans le CRM.","en":"Landing pages and targeted ad campaigns, with leads imported directly into the CRM."}'::jsonb, ARRAY['LEAD_GENERATION','MARKETING']::text[], '{"fr":["Pas assez de leads vendeurs ou acheteurs","Dépendance au bouche-à-oreille"],"en":["Not enough seller or buyer leads","Relying on word of mouth"]}'::jsonb, '{"fr":["Landing pages pour attirer acheteurs et vendeurs","Publicités Facebook et Instagram ciblées par région ou code postal (service optionnel)","Google Ads gérés par des experts (service optionnel)","Leads importés dans le CRM avec notification"],"en":["Landing pages to attract buyers and sellers","Facebook & Instagram ads targeted by area or postal code (optional service)","Google Ads managed by experts (optional service)","Leads imported into the CRM with notification"]}'::jsonb, '{"fr":"","en":""}'::jsonb, 'demo', 'https://utilmo.com/fr/crm-leads/', 20) ON CONFLICT (assistant_id, key) DO NOTHING;
INSERT INTO recommended_services (organization_id, assistant_id, key, name, description, categories, problems, features, price_note, next_step, url, sort) VALUES ((SELECT id FROM organizations WHERE slug = 'utilmo'), (SELECT id FROM assistants WHERE public_key = 'utilmo'), 'website', '{"fr":"Site web immobilier avec Centris/CREA","en":"Real estate website with Centris/CREA"}'::jsonb, '{"fr":"Sites web professionnels pour courtiers et agences, conçus par l''IA ou sur mesure, avec intégration Centris ou CREA.","en":"Professional websites for brokers and agencies, AI-designed or custom, with Centris or CREA integration."}'::jsonb, ARRAY['WEBSITE','BRANDING']::text[], '{"fr":["Pas de site web ou site désuet","Faible conversion des visiteurs","Inscriptions non affichées"],"en":["No website or outdated website","Low visitor conversion","Listings not displayed"]}'::jsonb, '{"fr":["Intégration Centris ou CREA incluse","Forfaits Essentiel, Pro et Élite","Pages de propriétés non comptées dans le maximum de pages","Accès au CRM Utilmo et à la génération de leads (Essentiel)"],"en":["Centris or CREA integration included","Essential, Pro and Elite plans","Property pages not counted in the page limit","Access to Utilmo CRM and lead generation (Essential)"]}'::jsonb, '{"fr":"Essentiel : 1 000 $ + 129,99 $/mois (hébergement, intégration MLS et CRM inclus). Pro : 2 000 $. Élite : 3 500 $.","en":"Essential: $1,000 + $129.99/month (hosting, MLS integration and CRM included). Pro: $2,000. Elite: $3,500."}'::jsonb, 'demo', 'https://utilmo.com/fr/site-web-pour-courtier-immobilier/', 30) ON CONFLICT (assistant_id, key) DO NOTHING;
