INSERT INTO knowledge_conflicts (organization_id, assistant_id, topic, description, source_urls, detected_by) VALUES ((SELECT id FROM organizations WHERE slug = 'utilmo'), (SELECT id FROM assistants WHERE public_key = 'utilmo'), 'Durée de l''essai gratuit / free trial length', 'CRM page and the 30-day trial page say 30-day free trial; Schedule Demo and Onboarding pages show a ''14-Day Free Trial'' button.', ARRAY['https://utilmo.com/crm-leads/','https://utilmo.com/30-day-free-trial/','https://utilmo.com/schedule-demo/','https://utilmo.com/onboarding/']::text[], 'seed');
INSERT INTO knowledge_conflicts (organization_id, assistant_id, topic, description, source_urls, detected_by) VALUES ((SELECT id FROM organizations WHERE slug = 'utilmo'), (SELECT id FROM assistants WHERE public_key = 'utilmo'), 'Nombre de modèles du forfait Essentiel / Essential template count', 'Website pricing page says ''Choice of 17 Templates''; free-trial page says ''Choice of 12 Templates'' and ''Fixed Site Map''.', ARRAY['https://utilmo.com/real-estate-website-design/','https://utilmo.com/30-day-free-trial/']::text[], 'seed');
INSERT INTO knowledge_conflicts (organization_id, assistant_id, topic, description, source_urls, detected_by) VALUES ((SELECT id FROM organizations WHERE slug = 'utilmo'), (SELECT id FROM assistants WHERE public_key = 'utilmo'), 'Promotion site web 500 $ / $500 website promo', 'Promo page says ''Today only! Save $500 on your website'' — time-limited, validity unknown. Not to be promised until confirmed.', ARRAY['https://utilmo.com/fr/promo/']::text[], 'seed');
